13	
14	#include "adv_api/reduce/reduce.h"
15	#include "adv_api/broadcast/broadcast.h"
16	
17	namespace Atvoss::Tile {
18	
19	/*!
20	 * \brief Broadcast all input elements
21	 * \param[in] src, Input LocalTensor
22	 * \param[out] dst, Output LocalTensor
23	 */
24	template <typename OperationShape, Pattern pattern, typename T>
25	__aicore__ inline void BroadcastAssign(
26	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
27	{
28	    uint32_t dstShape[] = {operationShape.axis0, operationShape.axis1};
29	    if constexpr (pattern == Pattern::AB) {
30	        uint32_t srcShape_[] = {operationShape.axis0, 1};
31	        AscendC::Broadcast<T, 2, 1>(dst, src, dstShape, srcShape_);
32	    } else if constexpr (pattern == Pattern::BA) {
33	        uint32_t srcShape_[] = {1, operationShape.axis1};
34	        AscendC::Broadcast<T, 2, 0>(dst, src, dstShape, srcShape_);
35	    } else {
36	    }
37	}
38	
39	/*!
40	 * \brief Sum all input elements
41	 * \param[in] src, Input LocalTensor
42	 * \param[out] dst, Output LocalTensor
43	 */
44	template <typename OperationShape, Atvoss::Pattern pattern, typename T>
45	__aicore__ inline void ReduceSumAssign(
46	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
47	{
48	    uint32_t shape[] = {operationShape.axis0, operationShape.axis1};
49	    if constexpr (pattern == Atvoss::Pattern::AR) {
50	        AscendC::ReduceSum<T, AscendC::Pattern::Reduce::AR, true>(dst, src, shape, true);
51	    } else if constexpr (pattern == Atvoss::Pattern::RA) {
52	        AscendC::ReduceSum<T, AscendC::Pattern::Reduce::RA, true>(dst, src, shape, true);
53	    } else {
54	    }
55	}
56	
57	/*!
58	 * \brief Broadcast calculation based on the expression
59	 * \param[in] args, LocalTensor data of input tensors & output tensor
60	 * \param[in] localVar, LocalTensor data of temp tensors
61	 * \param[in] tail, Calculate the length of the data
62	 * \return Broadcast Expression calculation
63	 */
64	template <typename T, typename U, Atvoss::Pattern pattern>
65	struct Evaluator<OpAssign<T, OpBroadcast<pattern, U>>> {
66	    using Type = void;
67	
68	    template <typename Context>
69	    __aicore__ inline auto operator()(const OpAssign<T, OpBroadcast<pattern, U>>& op, Context& context) const
70	    {
71	        using Dtype = Dtype_t<T>;
72	        OperationShape operationShape = GetShape<Operation::Binary>(context.argsTensors);
73	        return Atvoss::Tile::BroadcastAssign<OperationShape, pattern, Dtype>(
74	            Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
75	            Evaluator<U>{}(op.GetRhs().GetData(), context).GetUbTensor(), operationShape);
76	    }
77	};
78	
79	/*!
80	 * \brief ReduceSum calculation based on the expression
81	 * \param[in] args, LocalTensor data of input tensors & output tensor
82	 * \param[in] localVar, LocalTensor data of temp tensors
83	 * \param[in] tail, Calculate the length of the data
84	 * \return ReduceSum Expression calculation
85	 */
86	template <typename T, typename U, Atvoss::Pattern pattern>
87	struct Evaluator<OpAssign<T, OpReduceSum<pattern, U>>> {
88	    using Type = void;
89	
90	    template <typename Context>
91	    __aicore__ inline auto operator()(const OpAssign<T, OpReduceSum<pattern, U>>& op, Context& context) const
92	    {
93	        using Dtype = Dtype_t<T>;
94	        OperationShape operationShape = GetShape<Operation::Binary>(context.argsTensors);
95	        return Atvoss::Tile::ReduceSumAssign<OperationShape, pattern, Dtype>(
96	            Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
97	            Evaluator<U>{}(op.GetRhs().GetData(), context).GetUbTensor(), operationShape);
98	    }
99	};
100	} // namespace Atvoss::Tile
101	
102	#endif // ATVOSS_TILE_ASCENDC_MATH_H
