#ifndef ATVOSS_DEV_PATTERNS_H
#define ATVOSS_DEV_PATTERNS_H
namespace Atvoss {
enum class Pattern
{
    AR,
    RA,
    AB,
    BA
};

enum class CastMode
{
    CAST_NONE = 0,
    CAST_RINT,
    CAST_FLOOR,
    CAST_CEIL,
