8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	#include <cstddef>
12	#include <iostream>
13	#include <stdexcept>
14	#include <tuple>
15	#include <type_traits>
16	#include <utility>
17	#include <vector>
18	#include "kernel_operator.h"
19	#include "atvoss.h"
20	#include "example_common.h"
21	#include "command_line.h"
22	#include "utils/layout/shape.h"
23	
24	static constexpr int32_t HEIGHT = 1;
25	static constexpr int32_t WIDTH = 32;
26	static constexpr int32_t MAX_DIM = 2;
27	
28	template <typename T1, typename T2, typename T3>
29	struct RmsNormConfig {
30	    using DtypeV1 = T1;
31	    using DtypeV2 = T2;
32	    using DtypeV3 = T3;
33	    using TileShape = Atvoss::Shape<HEIGHT, WIDTH>;
34	
35	    struct RmsNormCompute {
36	        template <template <typename> class Tensor>
37	        __host_aicore__ constexpr auto Compute() const
38	        {
39	            auto in1 = Atvoss::PlaceHolder<1, Tensor<DtypeV1>, Atvoss::ParamUsage::IN>();
40	            auto in2 = Atvoss::PlaceHolder<2, Tensor<DtypeV2>, Atvoss::ParamUsage::IN>();
41	            auto out = Atvoss::PlaceHolder<3, Tensor<DtypeV3>, Atvoss::ParamUsage::OUT>();
42	            auto _1 = Atvoss::ReduceSum<Atvoss::Pattern::AR>(in1 * in1);
43	            auto _2 = Atvoss::Broadcast<Atvoss::Pattern::AB>(_1);
44	            auto _3 = in1 / Atvoss::Sqrt(Atvoss::Divs<WIDTH>(_2));
45	            return out = in2 * _3;
46	        }
47	    };
48	
49	    static constexpr Atvoss::Ele::DefaultBlockPolicy<TileShape> blockPolicy {
50	        TileShape{}
51	    };
52	    static constexpr Atvoss::Ele::DefaultKernelPolicy kernelPolicy {
53	        Atvoss::Ele::DefaultSegmentPolicy::UniformSegment
54	    };
55	
56	    using ArchTag = Atvoss::Arch::DAV_3510;
57	    using BlockOp = Atvoss::Ele::BlockBuilder<
58	        RmsNormCompute,
59	        ArchTag,
60	        blockPolicy,
61	        Atvoss::Ele::DefaultBlockConfig>;
62	
63	    using KernelOp = Atvoss::Ele::KernelBuilder<
64	        BlockOp,
65	        kernelPolicy>;
66	
67	    using DeviceOp = Atvoss::DeviceAdapter<KernelOp>;
68	};
69	
70	
71	struct Options {
72	    // 存储解析后的值
73	    std::vector<int> shape;
74	    bool help;
75	
76	    // 默认构造：不解析，只设默认值
77	    Options() : shape({}), help(false)
78	    {
79	    }
80	
81	    // 解析函数
82	    void parse(int argc, char const* argv[])
83	    {
84	        CommandLine cmd(argc, argv);
85	
86	        help = cmd.Present("help") || cmd.Present("h");
87	        shape = cmd.Get("shape", std::vector<int>{});
88	
89	        validate(argv[0]);
90	    }
91	
92	    // 打印使用说明
93	    void PrintUsage(const char* progName = nullptr) const
94	    {
95	        if (!progName)
96	            progName = "program";
97	
98	        std::cout << "Usage: " << progName << " [options]\n"
99	                  << "\n"
100	                  << "Options:\n"
101	                  << "  --help                      Print this message\n"
102	                  << "  --shape=M,N,...           Tensor dimensions (e.g., --shape=512,32)\n"
103	                  << "\n"
104	                  << "Example:\n"
105	                  << "  " << progName << " --shape=512,32 \n";
106	    }
107	
108	    // 打印当前配置
109	    void print() const
110	    {
111	        std::cout << "Configuration:\n";
112	        std::cout << "  Tensor Shape [" << shape.size() << "D]: (";
113	        for (size_t i = 0; i < shape.size(); ++i) {
114	            std::cout << shape[i];
115	            if (i != shape.size() - 1)
116	                std::cout << ", ";
117	        }
118	        std::cout << ")\n";
119	    }
120	
121	private:
122	    static std::string ToLower(std::string s)
123	    {
124	        std::transform(s.begin(), s.end(), s.begin(), ::tolower);
125	        return s;
126	    }
127	
128	    void validate(const char* progName)
129	    {
130	        if (help) {
131	            return;  // 帮助不需要验证
132	        }
133	
134	        if (shape.empty()) {
135	            std::cerr << "[ERROR] Missing required argument: --shape\n";
136	            PrintUsage(progName);
137	            exit(1);
138	        }
139	        if (shape.size() > MAX_DIM) {
140	            std::cerr << "[ERROR] Input shape max dim is 2, current shape dim is: " << shape.size() << "\n";
141	            PrintUsage(progName);
142	            exit(1);
143	        }
144	        for (int d : shape) {
145	            if (d < 0) {
146	                std::cerr << "[ERROR] Invalid dimension size: " << d << "\n";
147	                exit(1);
148	            }
149	        }
150	    }
151	};
152	
153	template <typename T1, typename T2, typename T3>
154	static void Run(const Options& options)
155	{
156	    // --- Step 1: ACL 初始化 ---
157	    CHECK_ACL_RET(aclInit(nullptr));
158	    auto finalizeGuard = ReleaseSource([]() { aclFinalize(); });
159	
160	    // --- Step 2: 设置 device ---
161	    const int32_t deviceId = 0;
162	    CHECK_ACL_RET(aclrtSetDevice(deviceId));
163	    auto deviceResetGuard = ReleaseSource([deviceId]() { aclrtResetDevice(deviceId); });
164	
165	    // --- Step 3: 创建 Context ---
166	    aclrtContext context = nullptr;
167	    CHECK_ACL_RET(aclrtCreateContext(&context, deviceId));
168	    auto contextDestroyGuard = ReleaseSource([context]() { aclrtDestroyContext(context); });
169	
170	    // --- Step 4: 创建 Stream ---
171	    aclrtStream stream = nullptr;
172	    CHECK_ACL_RET(aclrtCreateStream(&stream));
173	    auto streamDestroyGuard = ReleaseSource([stream]() { aclrtDestroyStream(stream); });
174	
175	    // --- Step 5: 准备数据 ---
176	    const auto& shape = options.shape;
177	    const size_t shapeSize = std::accumulate(shape.begin(), shape.end(), size_t{1}, std::multiplies<>{});
178	    const size_t inputSize = shapeSize * sizeof(T1);
179	    const size_t outputSize = shapeSize * sizeof(T3);
180	
181	    // --- Step 6: 分配设备内存 ---
182	    void* rawInput1 = nullptr;
183	    CHECK_ACL_RET(aclrtMalloc(&rawInput1, inputSize, ACL_MEM_MALLOC_HUGE_FIRST));
184	    auto inputFreeGuard1 = ReleaseSource([rawInput1]() { aclrtFree(rawInput1); });
185	    T1* deviceInput1 = static_cast<T1*>(rawInput1);
186	
187	    void* rawInput2 = nullptr;
188	    CHECK_ACL_RET(aclrtMalloc(&rawInput2, inputSize, ACL_MEM_MALLOC_HUGE_FIRST));
189	    auto inputFreeGuard2 = ReleaseSource([rawInput2]() { aclrtFree(rawInput2); });
190	    T2* deviceInput2 = static_cast<T2*>(rawInput2);
191	
192	    void* rawOutput = nullptr;
193	    CHECK_ACL_RET(aclrtMalloc(&rawOutput, outputSize, ACL_MEM_MALLOC_HUGE_FIRST));
194	    auto outputFreeGuard = ReleaseSource([rawOutput]() { aclrtFree(rawOutput); });
195	    T3* deviceOutput = static_cast<T3*>(rawOutput);
196	
197	    // --- Step 7: Host -> Device 数据拷贝 ---
198	    std::vector<T1> hostInput1(shapeSize, static_cast<T1>(1.0F));
199	    CHECK_ACL_RET(aclrtMemcpy(deviceInput1, inputSize, hostInput1.data(), inputSize, ACL_MEMCPY_HOST_TO_DEVICE));
200	
201	    std::vector<T2> hostInput2(shapeSize, static_cast<T2>(2.0F));
202	    CHECK_ACL_RET(aclrtMemcpy(deviceInput2, inputSize, hostInput2.data(), inputSize, ACL_MEMCPY_HOST_TO_DEVICE));
203	
204	    // --- Step 8: 构造 Tensor 并执行算子 ---
205	    uint64_t shapeArray[MAX_DIM] = {0};
206	    std::copy(shape.begin(), shape.end(), shapeArray);
207	    Atvoss::Tensor<T1> t1(deviceInput1, shapeArray, shape.size());
208	    Atvoss::Tensor<T2> t2(deviceInput2, shapeArray, shape.size());
209	    Atvoss::Tensor<T3> t3(deviceOutput, shapeArray, shape.size());
210	    auto arguments = Atvoss::ArgumentsBuilder{}.inputOutput(t1, t2, t3).build();
211	
212	    using DeviceOp = typename RmsNormConfig<T1, T2, T3>::DeviceOp;
213	    DeviceOp deviceOp;
214	    deviceOp.Run(arguments, stream);
215	
216	    // --- Step 9: 同步并拷回结果 ---
217	    CHECK_ACL_RET(aclrtSynchronizeStream(stream));
218	    std::vector<T3> hostOutput(shapeSize);
219	    CHECK_ACL_RET(aclrtMemcpy(hostOutput.data(), outputSize, deviceOutput, outputSize, ACL_MEMCPY_DEVICE_TO_HOST));
220	
221	    // --- Step 10: 验证结果 ---
222	    std::vector<T3> golden(shapeSize, 2.0f);
223	    if (!VerifyResults(golden, hostOutput)) {
224	        std::cout << "Accuracy verification failed." << std::endl;
225	    } else {
226	        std::cout << "Accuracy verification passed." << std::endl;
227	    }
228	}
229	
230	int main(int argc, char const* argv[])
231	{
232	    Options options;
233	    options.parse(argc, argv);
234	
235	    if (options.help) {
236	        options.PrintUsage(argv[0]);
237	        return 0;
238	    }
