32	template <typename T1, typename T2, typename T3, int32_t TileLen>
33	struct RmsNormConfig {
34	    using DtypeV1 = T1;
35	    using DtypeV2 = T2;
36	    using DtypeV3 = T3;
37	    using TileShape = Atvoss::Shape<HEIGHT, TileLen>;
38	
39	    struct RmsNormCompute {
40	        template <template <typename> class Tensor>
41	        __host_aicore__ constexpr auto Compute() const
42	        {
43	            auto in1 = Atvoss::PlaceHolder<1, Tensor<DtypeV1>, Atvoss::ParamUsage::IN>();
44	            auto in2 = Atvoss::PlaceHolder<2, Tensor<DtypeV2>, Atvoss::ParamUsage::IN>();
45	            auto out = Atvoss::PlaceHolder<3, Tensor<DtypeV3>, Atvoss::ParamUsage::OUT>();
46	            auto temp = Atvoss::PlaceHolderTmpLike<1>(in1);
47	
48	            return (
49	                temp = in1 * in1, out = ReduceSum<Atvoss::Pattern::AR>(temp), out = Broadcast<Atvoss::Pattern::AB>(out),
50	                temp = Divs<TileLen>(out), out = Sqrt(temp), temp = in1 / out, out = in2 * temp);
51	        };
52	    };
53	
54	    static constexpr Atvoss::Ele::DefaultBlockPolicy<TileShape> blockPolicy{TileShape{}};
55	    static constexpr Atvoss::Ele::DefaultKernelPolicy kernelPolicy{Atvoss::Ele::DefaultSegmentPolicy::UniformSegment};
56	
57	    using ArchTag = Atvoss::Arch::DAV_3510;
58	    using BlockOp = Atvoss::Ele::BlockBuilder<RmsNormCompute, ArchTag, blockPolicy, Atvoss::Ele::DefaultBlockConfig>;
59	
60	    using KernelOp = Atvoss::Ele::KernelBuilder<BlockOp, kernelPolicy>;
61	
62	    using DeviceOp = Atvoss::DeviceAdapter<KernelOp>;
63	};
