65	struct Options {
66	    // 存储解析后的值
67	    std::vector<int> shape;
68	    bool help;
69	
70	    // 默认构造：不解析，只设默认值
71	    Options() : shape({}), help(false)
72	    {}
73	};
74	
75	template <typename T1, typename T2, typename T3, int32_t TileLen>
76	static void Run(const Options& options)
77	{
78	    // --- Step 1: ACL 初始化 ---
79	    CHECK_ACL_RET(aclInit(nullptr));
80	    auto finalizeGuard = ReleaseSource([]() { aclFinalize(); });
81	
82	    // --- Step 2: 设置 device ---
83	    const int32_t deviceId = 0;
84	    CHECK_ACL_RET(aclrtSetDevice(deviceId));
85	    auto deviceResetGuard = ReleaseSource([deviceId]() { aclrtResetDevice(deviceId); });
86	
87	    // --- Step 3: 创建 Context ---
88	    aclrtContext context = nullptr;
89	    CHECK_ACL_RET(aclrtCreateContext(&context, deviceId));
90	    auto contextDestroyGuard = ReleaseSource([context]() { aclrtDestroyContext(context); });
91	
92	    // --- Step 4: 创建 Stream ---
93	    aclrtStream stream = nullptr;
94	    CHECK_ACL_RET(aclrtCreateStream(&stream));
95	    auto streamDestroyGuard = ReleaseSource([stream]() { aclrtDestroyStream(stream); });
96	
97	    // --- Step 5: 准备数据 ---
98	    const auto& shape = options.shape;
99	    const size_t shapeSize = std::accumulate(shape.begin(), shape.end(), size_t{1}, std::multiplies<>{});
